div.script:

document.title = "dormo.io";

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

let player = {
  x: 300,
  y: 200,
  size: 10,
  dx: 2,
  dy: 0,
  trail: []
};

let score = 0;

window.addEventListener('keydown', e => {
  if ((e.key === 'ArrowUp' || e.key === 'w') && player.dy === 0) { player.dx = 0; player.dy = -2; }
  if ((e.key === 'ArrowDown' || e.key === 's') && player.dy === 0) { player.dx = 0; player.dy = 2; }
  if ((e.key === 'ArrowLeft' || e.key === 'a') && player.dx === 0) { player.dx = -2; player.dy = 0; }
  if ((e.key === 'ArrowRight' || e.key === 'd') && player.dx === 0) { player.dx = 2; player.dy = 0; }
});

function update() {
  player.x += player.dx;
  player.y += player.dy;

  // Screen boundaries
  if (player.x < 0) player.x = canvas.width;
  if (player.x > canvas.width) player.x = 0;
  if (player.y < 0) player.y = canvas.height;
  if (player.y > canvas.height) player.y = 0;

  // Save trail
  if (Math.random() < 0.3) {
    player.trail.push({x: player.x, y: player.y});
    if (player.trail.length > 150) player.trail.shift();
    score = Math.min(100, Math.floor(player.trail.length * 0.7));
    document.getElementById('scoreDisplay').textContent = "Territory Captured: " + score + "%";
  }
}

function draw() {
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw trail
  ctx.fillStyle = '#f97316';
  player.trail.forEach(t => {
    ctx.fillRect(t.x - 4, t.y - 4, 8, 8);
  });

  // Draw player head
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
  ctx.fill();
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
